#include <bits/stdc++.h>using namespace std; int main() {	// your code goes here	int T;	cin >> T;		while(T --){	int n, x;	cin >> n >> x;		vector<int>a(n);		for(auto &x : a){	    cin >> x;	}	    int ans = 0;     long long L = a[0] - x;    long long R = a[0] + x;        for(int i = 1; i < n; i++) {        long long l = a[i] - x;        long long r = a[i] + x;            // check intersection        if(max(L, l) <= min(R, r)) {            // shrink to intersection            L = max(L, l);            R = min(R, r);        } else {            // break → need change            ans++;            L = l;            R = r;        }    }        cout << ans << endl;	}}